import { join } from 'path';
import { v4 as uuidv4 } from 'uuid';
import { QAResponse, QAHistory, Citation, ConversationExchange } from '../shared/types';
import { PersistenceService } from './persistence-service';
import { IndexingService } from './indexing-service';
import { logger } from './logger';
import { toPlainExcerptText, truncateAtWord } from '../shared/text';

const QA_HISTORY_FILE = 'qa-history.json';

/** Mock Q&A patterns keyed to document content keywords. */
const MOCK_PATTERNS: Array<{
  keywords: string[];
  answer: string;
  excerpt: string;
}> = [
  {
    keywords: ['design', 'architecture', 'pattern'],
    answer: 'The system uses a layered architecture with clear boundaries between the main process, preload scripts, and renderer. Each layer communicates through typed IPC channels, and the services layer handles business logic independently of the UI.',
    excerpt: 'The system uses a layered architecture with clear boundaries',
  },
  {
    keywords: ['import', 'document', 'file'],
    answer: 'Documents are imported by copying the source file to the local data directory. The system extracts text content and creates metadata including title, filename, size, and import timestamp. After import, documents can be indexed for search.',
    excerpt: 'Documents are imported by copying the source file',
  },
  {
    keywords: ['index', 'chunk', 'search'],
    answer: 'The indexing pipeline splits documents into chunks of approximately 500 characters at paragraph boundaries. Each chunk includes metadata like character count and word count. The index enables grounded Q&A with citations pointing to specific document sections.',
    excerpt: 'The indexing pipeline splits documents into chunks',
  },
  {
    keywords: ['retrieval', 'search', 'query'],
    answer: 'Retrieval works by matching query keywords against indexed chunks. The system ranks chunks by keyword overlap and returns the most relevant excerpts as citations alongside the generated answer.',
    excerpt: 'Retrieval works by matching query keywords against indexed chunks',
  },
  {
    keywords: ['meeting', 'notes', 'summary'],
    answer: 'The meeting summary indicates that the team discussed implementing a retrieval-augmented generation pipeline. Key decisions included using local chunk storage and citation-based verification to ensure answer accuracy.',
    excerpt: 'The team discussed implementing a retrieval-augmented generation pipeline',
  },
];

const EXCERPT_CHARS = 200;

/** How many earlier turns of a follow-up chain are added to the retrieval context. */
const MAX_CONTEXT_TURNS = 5;

/** Common words that must not drive keyword retrieval on their own. */
const STOP_WORDS = new Set([
  'the', 'and', 'but', 'for', 'nor', 'not', 'yet', 'are', 'was', 'were', 'has', 'have', 'had',
  'does', 'did', 'can', 'could', 'should', 'would', 'will', 'what', 'when', 'where', 'which',
  'who', 'whom', 'why', 'how', 'this', 'that', 'these', 'those', 'then', 'than', 'there', 'their',
  'they', 'them', 'with', 'from', 'into', 'about', 'more', 'some', 'any', 'all', 'you', 'your',
  'its', 'our', 'also', 'just', 'say', 'says', 'tell', 'explain', 'please', 'other', 'such',
]);

/** Shorten chunk text to a plain one-line excerpt that ends on a word boundary and is marked when cut. */
export function toExcerpt(content: string, max = EXCERPT_CHARS): string {
  return truncateAtWord(toPlainExcerptText(content), max);
}

/** Lower-cased content words of a query, without punctuation or stop words. */
export function retrievalTerms(text: string): string[] {
  return text
    .toLowerCase()
    .split(/[^\p{L}\p{N}]+/u)
    .filter(w => w.length > 2 && !STOP_WORDS.has(w));
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function normalizeCitation(value: unknown): Citation | null {
  if (!isRecord(value) || typeof value.documentId !== 'string') return null;
  return {
    documentId: value.documentId,
    documentTitle: typeof value.documentTitle === 'string' ? value.documentTitle : 'Unknown Document',
    chunkIndex: typeof value.chunkIndex === 'number' ? value.chunkIndex : 0,
    excerpt: typeof value.excerpt === 'string' ? value.excerpt : '',
  };
}

/**
 * Normalize one persisted history entry, or return null when it cannot be
 * shown (no question text or no answer). Entries saved before conversation
 * support get a stable index-based id and fall back to the response timestamp
 * for `askedAt`.
 */
function normalizeEntry(entry: unknown, index: number): ConversationExchange | null {
  if (!isRecord(entry) || typeof entry.question !== 'string') return null;
  const response = entry.response;
  if (!isRecord(response) || typeof response.answer !== 'string') return null;

  const timestamp = typeof response.timestamp === 'string' ? response.timestamp
    : typeof entry.askedAt === 'string' ? entry.askedAt : '';
  const citations = Array.isArray(response.citations)
    ? response.citations.map(normalizeCitation).filter((c): c is Citation => c !== null)
    : [];
  return {
    id: typeof entry.id === 'string' && entry.id ? entry.id : `legacy-${index}`,
    question: entry.question,
    askedAt: typeof entry.askedAt === 'string' ? entry.askedAt : timestamp,
    followUpOf: typeof entry.followUpOf === 'string' ? entry.followUpOf : null,
    response: {
      answer: response.answer,
      citations,
      confidence: typeof response.confidence === 'number' ? response.confidence : 0,
      timestamp,
    },
  };
}

function describeWriteError(err: unknown): string {
  const code = (err as NodeJS.ErrnoException | undefined)?.code;
  switch (code) {
    case 'EACCES':
    case 'EPERM':
    case 'EROFS':
      return 'the file is not writable (permission denied)';
    case 'ENOSPC':
      return 'the disk is full';
    default:
      return code ? `system error ${code}` : 'an unexpected error occurred';
  }
}

export class QaService {
  private persistence: PersistenceService;
  private indexingService: IndexingService;
  private log = logger.forService('QaService');
  /** Bumped by clearHistory(); answers to questions asked before a clear are not saved. */
  private clearGeneration = 0;

  constructor(persistence: PersistenceService, indexingService?: IndexingService) {
    this.persistence = persistence;
    this.indexingService = indexingService ?? new IndexingService(persistence);
    this.log.info('QaService initialized');
  }

  /**
   * Ask a question and get a grounded answer with citations.
   *
   * When `followUpOf` names an earlier exchange, the questions of that
   * exchange and its own ancestors (up to MAX_CONTEXT_TURNS) are added to the
   * retrieval context, so a chain of short follow-ups ("and then?" → "why?")
   * keeps the original topic.
   *
   * If the history is cleared while the answer is being prepared, the answer
   * is returned but not saved: the user asked for an empty conversation.
   */
  async ask(question: string, followUpOf?: string): Promise<QAResponse> {
    question = typeof question === 'string' ? question.trim() : '';
    if (!question) {
      throw new Error('Question must be a non-empty string');
    }
    const generation = this.clearGeneration;
    const askedAt = new Date().toISOString();
    const conversation = followUpOf ? this.getConversation() : [];
    const byId = new Map(conversation.map(e => [e.id, e]));
    const parent = followUpOf ? byId.get(followUpOf) : undefined;
    if (followUpOf && !parent) {
      this.log.warn('Follow-up target not found, answering standalone', { followUpOf });
    }
    const contextTurns = this.ancestorQuestions(parent, byId);
    const context = [...contextTurns, question].join(' ');
    this.log.info('Processing question', { question, followUpOf: parent?.id ?? null, contextTurns: contextTurns.length });

    // Simulate processing delay
    await new Promise(resolve => setTimeout(resolve, 100 + Math.random() * 400));

    const chunks = this.indexingService.getAllChunks();
    const citations: Citation[] = [];

    this.log.info('Retrieving from chunks', { totalChunks: chunks.length });

    if (chunks.length > 0) {
      // Find relevant chunks using keyword matching on content words
      const questionWords = [...new Set(retrievalTerms(context))];
      const scored = chunks.map(chunk => {
        const contentLower = chunk.content.toLowerCase();
        const score = questionWords.reduce(
          (acc, word) => acc + (contentLower.includes(word) ? 1 : 0),
          0
        );
        return { chunk, score };
      });

      // Take top 2 relevant chunks as citations
      const relevant = scored
        .filter(s => s.score > 0)
        .sort((a, b) => b.score - a.score)
        .slice(0, 2);

      this.log.info('Keyword matching results', {
        questionWords: questionWords.length,
        relevantChunks: relevant.length,
      });

      // Get document metadata for citations
      const docs = this.persistence.readJson<Array<{ id: string; title: string }>>('documents-meta.json') ?? [];

      for (const { chunk } of relevant) {
        const doc = docs.find(d => d.id === chunk.documentId);
        citations.push({
          documentId: chunk.documentId,
          documentTitle: doc?.title ?? 'Unknown Document',
          chunkIndex: chunk.index,
          excerpt: toExcerpt(chunk.content),
        });
      }
    }

    // Generate answer from mock patterns or use fallback
    const answer = this.generateAnswer(context, citations);

    const response: QAResponse = {
      answer,
      citations,
      confidence: citations.length > 0 ? 0.85 : 0.3,
      timestamp: new Date().toISOString(),
    };

    this.log.info('Q&A response generated', {
      confidence: response.confidence,
      citationCount: citations.length,
      answerLength: answer.length,
    });

    if (generation !== this.clearGeneration) {
      this.log.warn('History was cleared while the question was pending; answer not saved', { question });
      return response;
    }

    // Save to history
    this.saveToHistory({ id: uuidv4(), question, askedAt, followUpOf: parent?.id, response });

    return response;
  }

  /**
   * Get the history as a conversation, oldest exchange first. Entries that
   * cannot be shown (e.g. missing question or answer) are skipped with a WARN
   * log instead of hiding the whole conversation; they stay in the file.
   */
  getConversation(): ConversationExchange[] {
    const raw = this.readHistory();
    const exchanges: ConversationExchange[] = [];
    const skipped: number[] = [];
    raw.forEach((entry, index) => {
      const exchange = normalizeEntry(entry, index);
      if (exchange) exchanges.push(exchange);
      else skipped.push(index);
    });
    if (skipped.length > 0) {
      this.log.warn('Skipped malformed conversation history entries', {
        skipped: skipped.length,
        indices: skipped.slice(0, 20),
      });
    }
    return exchanges;
  }

  /** Clear the Q&A history. Answers still being prepared will not be saved. */
  clearHistory(): void {
    this.clearGeneration++;
    this.writeHistory([]);
    this.log.info('Q&A history cleared');
  }

  /** Questions of `parent` and its ancestors, oldest first. */
  private ancestorQuestions(
    parent: ConversationExchange | undefined,
    byId: Map<string, ConversationExchange>
  ): string[] {
    const questions: string[] = [];
    const seen = new Set<string>();
    let current = parent;
    while (current && !seen.has(current.id) && questions.length < MAX_CONTEXT_TURNS) {
      seen.add(current.id);
      questions.unshift(current.question);
      current = current.followUpOf ? byId.get(current.followUpOf) : undefined;
    }
    return questions;
  }

  private historyLocation(): string {
    return join(this.persistence.getDataDir(), QA_HISTORY_FILE);
  }

  /**
   * Read the raw persisted entries. A file that is not valid JSON or not a
   * list is reported with a user-facing message; it is never overwritten.
   */
  private readHistory(): unknown[] {
    let raw: unknown;
    try {
      raw = this.persistence.readJson<unknown>(QA_HISTORY_FILE);
    } catch (err) {
      this.log.error('Conversation history file could not be parsed', {
        file: this.historyLocation(),
        error: String(err),
      });
      throw this.unreadableError();
    }
    if (raw === null) return [];
    if (!Array.isArray(raw)) {
      this.log.error('Conversation history file is not a list', { file: this.historyLocation() });
      throw this.unreadableError();
    }
    return raw;
  }

  private unreadableError(): Error {
    return new Error(
      `The conversation history file is unreadable (${this.historyLocation()}). ` +
      'It was left unchanged. Repair or move that file, then press Refresh.'
    );
  }

  private writeHistory(entries: unknown[]): void {
    try {
      this.persistence.writeJson(QA_HISTORY_FILE, entries);
    } catch (err) {
      this.log.error('Conversation history could not be saved', {
        file: this.historyLocation(),
        error: String(err),
      });
      throw new Error(
        `Could not save to the conversation history file (${this.historyLocation()}): ${describeWriteError(err)}.`
      );
    }
  }

  private generateAnswer(question: string, citations: Citation[]): string {
    // Match against mock patterns
    const questionLower = question.toLowerCase();
    for (const pattern of MOCK_PATTERNS) {
      if (pattern.keywords.some(kw => questionLower.includes(kw))) {
        if (citations.length > 0) {
          return `${pattern.answer} Based on the document "${citations[0].documentTitle}", ${citations[0].excerpt.substring(0, 100)}.`;
        }
        return pattern.answer;
      }
    }

    // Fallback answer
    if (citations.length > 0) {
      return `Based on the available documents, the most relevant information comes from "${citations[0].documentTitle}": ${citations[0].excerpt.substring(0, 150)}. However, a more specific answer would require additional context.`;
    }

    return 'No relevant documents have been indexed yet. Please import and index documents before asking questions.';
  }

  private saveToHistory(entry: QAHistory): void {
    // Keep entries we cannot display untouched so nothing is silently lost.
    const history = this.readHistory();
    history.push(entry);
    this.writeHistory(history);
    this.log.info('Question saved to history', { historyLength: history.length });
  }
}
/** Cross-boundary type definitions shared between main, preload, and renderer. */

export interface Document {
  id: string;
