import { useEffect, useMemo, useRef, useState, type FormEvent, type KeyboardEvent } from 'react';
import { ConversationExchange } from '../../shared/types';
import { ExchangeItem } from './ExchangeItem';
import { errorBox, metaText, smallButton, userBubble } from '../styles';

export interface PendingQuestion {
  question: string;
  followUpOf: string | null;
}

export interface FailedQuestion extends PendingQuestion {
  message: string;
}

/** A request to scroll to and highlight an exchange; `seq` lets the same exchange be selected twice. */
export interface ExchangeSelection {
  id: string;
  seq: number;
}

interface Props {
  conversation: ConversationExchange[];
  historyError: string | null;
  pending: PendingQuestion | null;
  failed: FailedQuestion | null;
  selection: ExchangeSelection | null;
  now: Date;
  isDocumentAvailable: (documentId: string) => boolean;
  onAsk: (question: string, followUpOf: string | null) => void;
  onRetry: () => void;
  onDismissError: () => void;
  onClear: () => Promise<void>;
  onOpenCitation: (documentId: string, chunkIndex: number) => void;
  onSelectExchange: (exchangeId: string) => void;
}

export function QuestionPanel({
  conversation,
  historyError,
  pending,
  failed,
  selection,
  now,
  isDocumentAvailable,
  onAsk,
  onRetry,
  onDismissError,
  onClear,
  onOpenCitation,
  onSelectExchange,
}: Props) {
  const [question, setQuestion] = useState('');
  const [followUpId, setFollowUpId] = useState<string | null>(null);
  const [confirmingClear, setConfirmingClear] = useState(false);
  const [highlightedId, setHighlightedId] = useState<string | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const threadEndRef = useRef<HTMLDivElement>(null);
  const clearButtonRef = useRef<HTMLButtonElement>(null);
  /** Set when the confirmation is cancelled so focus returns to "Clear conversation" once it is back. */
  const restoreClearFocus = useRef(false);

  useEffect(() => {
    if (!confirmingClear && restoreClearFocus.current) {
      restoreClearFocus.current = false;
      clearButtonRef.current?.focus();
    }
  }, [confirmingClear]);

  const byId = useMemo(() => new Map(conversation.map(e => [e.id, e])), [conversation]);
