            </div>
          ) : (
            <button type="button" ref={clearButtonRef} onClick={() => setConfirmingClear(true)} style={smallButton}>
              Clear conversation
            </button>
          ))}
      </div>

      <div style={{ flex: 1, overflow: 'auto', padding: '12px 20px' }}>
        {historyError && (
          <div style={{ color: '#888', textAlign: 'center', paddingTop: '40px', fontSize: '14px' }}>
            The conversation could not be loaded. See the message above the question box.
          </div>
        )}

        {isEmpty && !historyError && (
          <div style={{ color: '#888', textAlign: 'center', paddingTop: '40px', fontSize: '14px', lineHeight: 1.6 }}>
            No questions yet.
            <br />
            <span style={{ fontSize: '12px' }}>
              Ask a question below — answers cite the indexed documents they are based on, and the whole conversation stays here.
            </span>
          </div>
        )}

        {/* role="log" sits on a wrapper so the <ol>/<li> keep their list semantics. */}
        <div role="log" aria-label="Questions and answers" aria-live="polite" aria-relevant="additions">
        <ol
          aria-label="Exchanges"
          style={{ listStyle: 'none', margin: 0, padding: 0, display: 'flex', flexDirection: 'column', gap: '12px' }}
        >
          {conversation.map(exchange => (
            <li key={exchange.id}>
              <ExchangeItem
                exchange={exchange}
                parent={exchange.followUpOf ? byId.get(exchange.followUpOf) ?? null : null}
                highlighted={highlightedId === exchange.id}
                now={now}
                isDocumentAvailable={isDocumentAvailable}
                onOpenCitation={onOpenCitation}
                onFollowUp={startFollowUp}
                onJumpTo={onSelectExchange}
              />
            </li>
          ))}

          {pending && (
            <li aria-busy="true" style={{ display: 'flex', flexDirection: 'column', gap: '8px', padding: '8px' }}>
              <div style={userBubble}>{pending.question}</div>
              <div style={{ ...metaText, alignSelf: 'flex-start', fontSize: '13px' }}>Assistant is searching your documents…</div>
            </li>
          )}

          {failed && (
            <li style={{ display: 'flex', flexDirection: 'column', gap: '8px', padding: '8px' }}>
              <div style={userBubble}>{failed.question}</div>
              <div role="alert" style={{ ...errorBox, alignSelf: 'flex-start', maxWidth: '88%' }}>
                <div>The question could not be answered: {failed.message}</div>
                <div style={{ display: 'flex', gap: '6px', marginTop: '8px' }}>
                  <button type="button" onClick={onRetry} style={smallButton}>Retry</button>
                  <button type="button" onClick={onDismissError} style={smallButton}>Dismiss</button>
                </div>
              </div>
            </li>
          )}
        </ol>
        </div>
        <div ref={threadEndRef} />
      </div>

      <form
        onSubmit={handleSubmit}
        style={{
          display: 'flex',
          flexDirection: 'column',
          gap: '6px',
          padding: '12px 20px',
          borderTop: '1px solid #0f3460',
          background: '#16213e',
        }}
      >
        {historyError && (
          <div role="alert" style={errorBox}>
            Could not load the conversation history. {historyError}
          </div>
        )}
        {followUpTarget && (
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px', fontSize: '12px', color: '#c0c0e0' }}>
            <span id="follow-up-context" style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
              ↪ Following up on “{followUpTarget.question}”
            </span>
            <button
              type="button"
              onClick={() => {
                setFollowUpId(null);
                inputRef.current?.focus();
              }}
              style={smallButton}
              aria-label="Cancel follow-up"
            >
              ✕
            </button>
          </div>
        )}
        <div style={{ display: 'flex' }}>
          <label htmlFor="question-input" className="visually-hidden">
            Ask a question about your documents
          </label>
          <input
            id="question-input"
            ref={inputRef}
            type="text"
            value={question}
            onChange={e => setQuestion(e.target.value)}
            onKeyDown={e => {
              if (e.key === 'Escape' && followUpTarget) {
                e.preventDefault();
                setFollowUpId(null);
              }
            }}
            aria-describedby={followUpTarget ? 'follow-up-context' : undefined}
            placeholder={followUpTarget ? 'Ask a follow-up question… (Esc to cancel)' : 'Ask a question about your documents...'}
            style={{
              flex: 1,
              padding: '10px 14px',
              background: '#1a1a2e',
              color: '#e0e0e0',
              border: '1px solid #0f3460',
              borderRadius: '6px',
              fontSize: '14px',
            }}
          />
          <button
            type="submit"
            disabled={!question.trim() || pending !== null}
            style={{
              marginLeft: '10px',
              padding: '10px 20px',
              background: '#533483',
              color: '#fff',
              border: 'none',
              borderRadius: '6px',
              cursor: 'pointer',
              fontSize: '14px',
              fontWeight: 500,
            }}
          >
            {pending ? 'Asking…' : 'Ask'}
          </button>
        </div>
      </form>
    </section>
  );
}
import { ConversationExchange } from '../../shared/types';
import { formatFullTimestamp, formatTimestamp } from '../format';

interface Props {
  conversation: ConversationExchange[];
  selectedId: string | null;
  now: Date;
  onSelect: (exchangeId: string) => void;
}

/** Sidebar index of past questions; selecting one jumps to it in the conversation. */
export function ConversationHistory({ conversation, selectedId, now, onSelect }: Props) {
  if (conversation.length === 0) {
    return (
      <div style={{ padding: '20px', color: '#888', textAlign: 'center', fontSize: '13px' }}>
        No conversation history yet. Ask a question to get started.
      </div>
    );
  }

  return (
    <nav aria-label="Past questions" style={{ flex: 1, overflow: 'auto' }}>
      <ol style={{ listStyle: 'none', margin: 0, padding: 0 }}>
        {conversation.map((exchange, i) => {
          const selected = exchange.id === selectedId;
          const citationCount = exchange.response.citations.length;
          return (
            <li key={exchange.id}>
              <button
                type="button"
                onClick={() => onSelect(exchange.id)}
                aria-current={selected ? 'true' : undefined}
                title={exchange.question}
                style={{
                  display: 'block',
                  width: '100%',
                  textAlign: 'left',
                  padding: '10px 16px',
                  background: selected ? '#0f3460' : 'transparent',
                  color: '#e0e0e0',
                  border: 'none',
                  borderBottom: '1px solid #0f3460',
                  cursor: 'pointer',
                  font: 'inherit',
                }}
              >
                <div style={{ fontSize: '13px', fontWeight: 500, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                  <span style={{ color: '#888' }}>{i + 1}. </span>
                  {exchange.question}
                </div>
                <div style={{ fontSize: '11px', color: '#9a9ac0', marginTop: '2px' }}>
                  <time dateTime={exchange.askedAt} title={formatFullTimestamp(exchange.askedAt)}>
                    {formatTimestamp(exchange.askedAt, now)}
                  </time>
                  {' · '}
                  {citationCount === 0 ? 'no sources' : `${citationCount} ${citationCount === 1 ? 'source' : 'sources'}`}
                  {exchange.followUpOf && ' · follow-up'}
                </div>
              </button>
            </li>
          );
        })}
      </ol>
    </nav>
  );
}
import { useEffect, useRef, useState } from 'react';
import { Citation, ConversationExchange } from '../../shared/types';
import { toPlainExcerptText, truncateAtWord } from '../../shared/text';
import { formatFullTimestamp, formatTimestamp } from '../format';
import { bubbleBase, metaText, smallButton, userBubble } from '../styles';

/** Answers longer than this start collapsed behind a "Show full answer" toggle. */
const LONG_ANSWER_CHARS = 1200;

interface Props {
  exchange: ConversationExchange;
  /** The exchange this one follows up on, when it is still in the history. */
  parent: ConversationExchange | null;
  highlighted: boolean;
  /** Reference time for "Today"/"Yesterday" labels; refreshed by the app at midnight. */
  now: Date;
  isDocumentAvailable: (documentId: string) => boolean;
  onOpenCitation: (documentId: string, chunkIndex: number) => void;
  onFollowUp: (exchange: ConversationExchange) => void;
  onJumpTo: (exchangeId: string) => void;
}

export function ExchangeItem({
  exchange,
  parent,
  highlighted,
  now,
  isDocumentAvailable,
  onOpenCitation,
  onFollowUp,
  onJumpTo,
}: Props) {
  const { response } = exchange;
  const isLong = response.answer.length > LONG_ANSWER_CHARS;
  const [expanded, setExpanded] = useState(false);
  const [showSources, setShowSources] = useState(true);
  const [copyStatus, setCopyStatus] = useState('');
  const copyTimer = useRef<number | undefined>(undefined);
  const answerId = `answer-${exchange.id}`;
  const sourcesId = `sources-${exchange.id}`;
  const confidencePct = Math.round(response.confidence * 100);
  const lowConfidence = response.confidence < 0.5;

  useEffect(() => () => window.clearTimeout(copyTimer.current), []);

  const copyAnswer = async () => {
    try {
      await navigator.clipboard.writeText(response.answer);
      setCopyStatus('Copied');
    } catch {
      setCopyStatus('Copy failed');
    }
    window.clearTimeout(copyTimer.current);
    copyTimer.current = window.setTimeout(() => setCopyStatus(''), 2000);
  };

  return (
    <article
      id={`exchange-${exchange.id}`}
      tabIndex={-1}
      aria-labelledby={`question-${exchange.id}`}
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '8px',
        padding: '8px',
        borderRadius: '8px',
        outlineOffset: '2px',
        background: highlighted ? 'rgba(83, 52, 131, 0.18)' : 'transparent',
        transition: 'background 0.3s',
      }}
    >
      {/* User question */}
      <div style={{ alignSelf: 'flex-end', display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: '4px', maxWidth: '80%' }}>
        <div style={metaText}>
          <span style={{ fontWeight: 600, color: '#c9b6ef' }}>You</span>
          {' · '}
          <time dateTime={exchange.askedAt} title={formatFullTimestamp(exchange.askedAt)}>
            {formatTimestamp(exchange.askedAt, now)}
          </time>
        </div>
        {exchange.followUpOf && (
          <div style={metaText}>
            {parent ? (
              <button
                type="button"
                onClick={() => onJumpTo(parent.id)}
                style={{ ...smallButton, border: 'none', padding: 0, color: '#9a9ac0', textDecoration: 'underline' }}
                title="Jump to the earlier question"
              >
                ↪ Follow-up to “{truncate(parent.question, 60)}”
              </button>
            ) : (
              <span>↪ Follow-up to an earlier question</span>
            )}
          </div>
        )}
        <h3 id={`question-${exchange.id}`} style={{ ...userBubble, maxWidth: '100%', fontWeight: 400, margin: 0 }}>
          {exchange.question}
        </h3>
      </div>

      {/* Assistant answer */}
      <div style={{ alignSelf: 'flex-start', maxWidth: '88%', display: 'flex', flexDirection: 'column', gap: '4px' }}>
        <div style={metaText}>
          <span style={{ fontWeight: 600, color: '#8fb3ff' }}>Assistant</span>
          {' · '}
          <time dateTime={response.timestamp} title={formatFullTimestamp(response.timestamp)}>
            {formatTimestamp(response.timestamp, now)}
          </time>
          {' · '}
          <span
            style={{ color: lowConfidence ? '#f0ad4e' : '#5cb85c' }}
            title="How well the answer is supported by your indexed documents"
          >
            {lowConfidence ? 'Low confidence' : 'Confidence'} {confidencePct}%
          </span>
        </div>
        <div
          style={{
            ...bubbleBase,
            background: '#1a1a3e',
            border: '1px solid #0f3460',
            borderBottomLeftRadius: '2px',
          }}
        >
          <div id={answerId}>
            {isLong && !expanded ? truncateAtWord(response.answer, LONG_ANSWER_CHARS) : response.answer}
          </div>
          {isLong && (
            <button
              type="button"
              aria-expanded={expanded}
              aria-controls={answerId}
              onClick={() => setExpanded(!expanded)}
              style={{ ...smallButton, marginTop: '8px' }}
            >
              {expanded ? 'Show less' : `Show full answer (${response.answer.length.toLocaleString()} characters)`}
            </button>
          )}

          {response.citations.length > 0 ? (
            <div style={{ marginTop: '12px', borderTop: '1px solid #0f3460', paddingTop: '8px', whiteSpace: 'normal' }}>
              <button
                type="button"
                aria-expanded={showSources}
                aria-controls={sourcesId}
                onClick={() => setShowSources(!showSources)}
                style={{ ...smallButton, border: 'none', padding: 0, fontWeight: 600, color: '#8888bb' }}
              >
                {showSources ? '▾' : '▸'} Sources ({response.citations.length})
              </button>
              {showSources && (
                <ol id={sourcesId} style={{ listStyle: 'none', margin: '6px 0 0', padding: 0, display: 'flex', flexDirection: 'column', gap: '6px' }}>
                  {response.citations.map((citation, i) => (
                    <CitationItem
                      key={`${citation.documentId}-${citation.chunkIndex}-${i}`}
                      number={i + 1}
                      citation={citation}
                      available={isDocumentAvailable(citation.documentId)}
                      onOpen={() => onOpenCitation(citation.documentId, citation.chunkIndex)}
                    />
                  ))}
                </ol>
              )}
            </div>
          ) : (
            <p style={{ marginTop: '10px', fontSize: '12px', fontStyle: 'italic', color: '#9a9ac0', whiteSpace: 'normal' }}>
              No sources cited — no indexed document matched this question, so the answer is not grounded in your documents.
            </p>
          )}
        </div>

        <div style={{ display: 'flex', gap: '6px', alignItems: 'center' }}>
          <button type="button" onClick={copyAnswer} style={smallButton} aria-label={`Copy answer to “${truncate(exchange.question, 60)}”`}>
            Copy answer
          </button>
          <button type="button" onClick={() => onFollowUp(exchange)} style={smallButton} aria-label={`Ask a follow-up to “${truncate(exchange.question, 60)}”`}>
            Follow up
          </button>
          <span role="status" style={metaText}>{copyStatus}</span>
        </div>
      </div>
    </article>
  );
}

function CitationItem({
  number,
  citation,
  available,
  onOpen,
}: {
  number: number;
  citation: Citation;
  available: boolean;
  onOpen: () => void;
}) {
  // Chunk indexes are 0-based internally; people count from 1.
  const label = `${citation.documentTitle} · chunk ${citation.chunkIndex + 1}`;
  // Older history entries stored raw markdown excerpts; show them as one clean line.
  const excerpt = toPlainExcerptText(citation.excerpt);
  return (
    <li style={{ paddingLeft: '8px', borderLeft: '2px solid #533483', fontSize: '12px' }}>
      <div style={{ display: 'flex', gap: '6px', alignItems: 'baseline', flexWrap: 'wrap' }}>
        <span style={{ color: '#8888bb' }}>[{number}]</span>
        {available ? (
          <button
            type="button"
            onClick={onOpen}
            title="Open this document at the cited chunk"
            style={{ ...smallButton, border: 'none', padding: 0, color: '#8fb3ff', textDecoration: 'underline' }}
          >
            {label}
          </button>
        ) : (
          <span style={{ color: '#8888bb' }}>
            {label} <em>(document no longer available)</em>
          </span>
        )}
      </div>
      {excerpt && (
        <blockquote
          title={excerpt}
          style={{
            margin: '4px 0 0',
            color: '#b0b0d0',
            whiteSpace: 'normal',
            overflowWrap: 'anywhere',
            lineHeight: 1.45,
            display: '-webkit-box',
            WebkitLineClamp: 3,
            WebkitBoxOrient: 'vertical',
            overflow: 'hidden',
          }}
        >
          {excerpt}
        </blockquote>
      )}
    </li>
  );
}

function truncate(text: string, max: number): string {
  return text.length > max ? `${text.slice(0, max - 1)}…` : text;
}

