  out('error text', await page.evaluate(`document.querySelector('[role=log] [role=alert]').innerText`));
  await page.screenshot('p07-error');
  out('focus after error', await page.evaluate(focused));
  chmodSync(hf, 0o644);
  await page.evaluate(clickBtn('Dismiss'));

  // corrupt file -> sidebar message
  writeFileSync(hf, '[{"question": ');
  await page.evaluate(clickBtn('Refresh'));
  await sleep(500);
  await page.evaluate(clickBtn('History'));
  out('corrupt sidebar', await page.evaluate(`document.querySelector('aside').innerText`));
  out('corrupt main', await page.evaluate(`document.querySelector('main').innerText`));
  await page.screenshot('p08-corrupt');

  page.close(); await quit();
  const logs = lastLogs.split('\n').filter(l => /ASK_QUESTION|GET_CONVERSATION|ERROR/.test(l)).slice(-4);
  out('logs', logs);
}
main().catch(e => console.log('FATAL', e)).finally(async () => { await quit().catch(()=>{}); rmSync(userDataDir, { recursive: true, force: true }); });
EOF
